    {
      "keystrokes": "ls -la references/\\n",
      "duration": 0.1
    },
    {
      "keystrokes": "cat references/agent-registry.json\\n",
      "duration": 0.1
    },
    {
      "keystrokes": "cat references/sap-helper-spec.yaml\\n",
      "duration": 0.1
    }
  ]
}
